#include <vector>
#include <string>
#include <algorithm>
#include <numeric>

class Solution {
public:
    long long maximizeSum(std::vector<int>& nums, int k) {
        std::vector<long long> gains;
        long long total = 0;
        for (int x : nums) {
            total += x;
            std::string s = std::to_string(x);
            std::sort(s.rbegin(), s.rend());
            long long val = std::stoll(s);
            gains.push_back(val - x);
        }
        std::sort(gains.rbegin(), gains.rend());
        for (int i = 0; i < std::min((int)gains.size(), k); ++i) {
            if (gains[i] > 0) total += gains[i];
        }
        return total;
    }
};

import java.util.*;

class Solution {
    public long maximizeSum(int[] nums, int k) {
        long total = 0;
        List<Long> gains = new ArrayList<>();
        for (int x : nums) {
            total += x;
            char[] chars = String.valueOf(x).toCharArray();
            Arrays.sort(chars);
            StringBuilder sb = new StringBuilder(new String(chars)).reverse();
            long rearranged = Long.parseLong(sb.toString());
            gains.add(rearranged - x);
        }
        gains.sort(Collections.reverseOrder());
        for (int i = 0; i < Math.min(gains.size(), k); i++) {
            if (gains.get(i) > 0) total += gains.get(i);
        }
        return total;
    }
}

var maximizeSum = function(nums, k) {
    let total = 0;
    const gains = [];
    for (const x of nums) {
        total += x;
        const rearranged = parseInt(String(x).split('').sort((a, b) => b.localeCompare(a)).join(''), 10);
        gains.push(rearranged - x);
    }
    gains.sort((a, b) => b - a);
    for (let i = 0; i < Math.min(gains.length, k); i++) {
        if (gains[i] > 0) total += gains[i];
    }
    return total;
};
